def test_summarize_empty():
    s = m.summarize([])
    assert s["queries"] == 0
    assert s["mrr"] == 0.0
    assert s["hit@1"] == 0.0
    assert s["hit@3"] == 0.0
    assert s["hit@5"] == 0.0


def test_summarize_values():
    ranks = [1, 2, None, 4]
    s = m.summarize(ranks)
    assert s["queries"] == 4
    assert abs(s["mrr"] - 0.4375) < 1e-9
    assert s["hit@1"] == 25.0
    assert s["hit@3"] == 50.0
    assert s["hit@5"] == 75.0


def test_render_markdown_structure():
    summaries = {"semantic": {"mrr": 0.5, "hit@1": 10.0, "hit@3": 20.0, "hit@5": 30.0}}
    latency = {"mean_s": 1.5, "max_s": 2.5}
    rows = [{"question": "Q1", "semantic": 1}]
    md = m.render_markdown(summaries, latency, rows, ["semantic"], "2023-01-01")
    assert "# Retrieval evaluation — 2023-01-01" in md
    assert "| semantic | 0.500 | 10.0% | 20.0% | 30.0% |" in md
    assert "| 1 | 1 | Q1 |" in md
    assert "Latency per question: mean 1.5 s, max 2.5 s" in md


